$reviewsData = [['first_name' => 'Светлана', 'middle_name' => null, 'last_name' => null, 'rating' => 5, 'desc_story' => 'Добрый день! Посещаю эту клинику уже много лет! Здесь я регулярно пользуюсь различными услугами эстетической медицины, такими как мезотерапия и инъекции красоты.', 'desc_like' => 'Всегда довольна результатом! Особенно положительное впечатление от врачей. Очень нравится, что ничего лишнего не навязывают, всё строго по показаниям. Оценка 5 из 5!', 'date' => '2024-06-10'], ['first_name' => 'Тамара', 'middle_name' => null, 'last_name' => null, 'rating' => 5, 'desc_story' => 'Обратились в клинику за помощью для моего ребенка, у сына были увеличенные аденоиды и проблемы с носовым дыханием.', 'desc_like' => 'Большое спасибо Абдулхакимову У.Ш и всему персоналу "Арт-Медика" за помощь моему ребенку! Проводили аденотомию, персонал очень дружелюбный, комфортная палата, на все вопросы подробно отвечали. После операции сыну выдали грамоту "Самый храбрый пациент", ребенок был счастлив! Очень благодарны вам!', 'date' => '2018-09-02'], ['first_name' => 'Антонина', 'middle_name' => null, 'last_name' => null, 'rating' => 5, 'desc_story' => 'Проходила курс профессиональных пилингов в клинике "Арт-Медика". Хотелось освежить кожу и выровнять цвет лица.', 'desc_like' => 'Проходила курс пилингов у Падалко Дарьи. Результат очень понравился, и доктор сразу к себе расположила. Подробно рассказала все о состоянии моей кожи, подобрала грамотную программу лечения. Претензий нет, только самые приятные впечатления!', 'date' => '2018-04-17'], ['first_name' => 'Ольга', 'middle_name' => null, 'last_name' => null, 'rating' => 5, 'desc_story' => 'Перегородка носа была сильно смещена, дышать челябинским воздухом особенно трудно, в итоге 3 года жила только с помощью сосудосуживающих капель для носа.', 'desc_like' => 'Посоветовали обратиться к Сергеевой Евгении Александровне — врач от Бога! Благодаря лечению я смогла дышать, сняли отек, теперь капли вообще не лежат в моей сумке! Через 3 месяца сделала операцию по исправлению перегородки в этом же центре. Только слова огромной благодарности! Теперь вся семья и друзья обслуживаются здесь!', 'date' => '2018-04-01'], ['first_name' => 'Мария', 'middle_name' => null, 'last_name' => null, 'rating' => 5, 'desc_story' => 'Осталась очень довольна. У ребёнка были аденоиды, носом почти не дышал, ночью сильно храпел. Обратились в "Арт-Медику" к ЛОРу Улугбеку Шавкатбековичу.', 'desc_like' => 'У меня сын очень капризный и боится врачей, но Улугбек Шавкатбекович сумел расположить его к себе с первых минут. Осмотр прошёл спокойно и тщательно, доктор назначил комплексные анализы и выявил причину. Было назначено комплексное лечение и теперь сын дышит носом свободно, ночью не храпит! Огромное спасибо доктору!', 'date' => '2017-11-26'], ['first_name' => 'Алия', 'middle_name' => null, 'last_name' => null, 'rating' => 5, 'desc_story' => 'С сыном попали на прием к детскому ЛОР-врачу. Сначала были на первичной консультации по акции для деток.', 'desc_like' => 'Очень понравилась подробная консультация, которая длилась больше получаса. Врач не стал торопиться назначать агрессивное лечение, а первым делом назначил точные анализы и тесты на аллергены. Общее впечатление от клиники и от доктора исключительно положительное!', 'date' => '2012-02-16'], ['first_name' => 'Екатерина', 'middle_name' => 'Владимировна', 'last_name' => 'М.', 'rating' => 5, 'desc_story' => 'Долго не могла решиться на блефаропластику, сильно мешали нависшие веки и уставший вид по утрам. Знакомые порекомендовали Юрия Юрьевича Перевезенцева как первоклассного специалиста.', 'desc_like' => 'Операция прошла под местной анестезией абсолютно безболезненно и очень спокойно. Результат превзошел все ожидания — открытый, молодой и свежий взгляд! Огромное спасибо всему персоналу клиники «Арт-Медика».', 'date' => '2026-10-18'], ['first_name' => 'Ольга', 'middle_name' => 'Николаевна', 'last_name' => 'С.', 'rating' => 5, 'desc_story' => 'Обратилась в клинику по рекомендации подруги для коррекции возрастных изменений нижних век («мешки» под глазами).', 'desc_like' => 'Очень заботливое отношение, стерильная чистота, современные палаты и золотые руки хирурга. Реабилитация заняла всего неделю, синяков практически не было. Рекомендую клинику от всей души!', 'date' => '2026-10-04'], ['first_name' => 'Марина', 'middle_name' => 'Сергеевна', 'last_name' => 'К.', 'rating' => 5, 'desc_story' => 'Делала риносептопластику у доктора Сергеевой Евгении Александровны. Нос почти не дышал с детства из-за искривленной перегородки.', 'desc_like' => 'Нос задышал свободно прямо сразу после удаления сплинтов! Форма получилась невероятно изящная и естественная, идеально гармонирует с чертами лица. Спасибо Евгении Александровне за ювелирную работу!', 'date' => '2026-09-05'], ['first_name' => 'Ирина', 'middle_name' => 'Викторовна', 'last_name' => 'П.', 'rating' => 5, 'desc_story' => 'Обратилась в отделение косметологии к Ирине Сергеевне Кузнецовой с проблемой потери упругости кожи и нечетким овалом лица. Доктор предложила аппаратный SMAS-лифтинг Ultraformer III.', 'desc_like' => 'Процедура абсолютно комфортная, эффект нарастал в течение двух месяцев. Кожа заметно подтянулась, контур нижней челюсти стал четким! Очень благодарна Ирине Сергеевне за чуткость и профессионализм.', 'date' => '2026-08-19'], ['first_name' => 'Татьяна', 'middle_name' => 'Григорьевна', 'last_name' => 'Д.', 'rating' => 5, 'desc_story' => 'Много лет мучилась с варикозом на правой ноге: к вечеру нога отекала и гудела, появились некрасивые синие узлы. На приеме Алексей Михайлович Барвинк выполнил УЗИ и порекомендовал лазерную коагуляцию ЭВЛК.', 'desc_like' => 'Вся манипуляция заняла меньше часа! Никакого наркоза и боли, встала и пошла домой своими ногами. Узлы исчезли, тяжесть в ногах ушла. Доктор — настоящий мастер своего дела!', 'date' => '2026-07-30']];
