        foreach ($lorServices as $srv) {
            if (!empty($lors)) {
                $srv->specialists()->syncWithoutDetaching($lors);
            }
        }

        // Связываем флебологию
        $phleboServices = Service::whereHas('category.section.sectionAll', function ($q) {
            $q->where('name', 'like', '%Флебология%');
        })->get();
        foreach ($phleboServices as $srv) {
            if (!empty($phlebologists)) {
                $srv->specialists()->syncWithoutDetaching($phlebologists);
            }
        }

        // Связываем неврологию
        $neuroServices = Service::whereHas('category.section.sectionAll', function ($q) {
            $q->where('name', 'like', '%Неврология%');
        })->get();
        foreach ($neuroServices as $srv) {
            if (!empty($neurologists)) {
                $srv->specialists()->syncWithoutDetaching($neurologists);
            }
        }

        // ==========================================
        // СВЯЗИ АКЦИЙ С УСЛУГАМИ (Promotion-Service links)
        // ==========================================
        $promoServiceMap = [
            "REVI" => ["Биоревитализация", "Мезотерапия"],
            "NOVAKUTAN" => ["Контурная пластика", "Биоревитализация", "Нитевой лифтинг"],
            "Белая коза" => ["Биоревитализация", "Уходы за лицом и телом"],
            "Agentcol" => ["Мезотерапия", "Биоревитализация"],
            "ДЕКАБРЬ" => ["Блефаропластика", "Ботокс/Диспорт", "Лазерная система Fotona SP Dynamis"],
            "ЛОР-акция" => ["Диагностика лор-органов", "Лечение лор-органов"],
            "меланомы" => ["Удаление родинок", "Клиническая дерматология"],
            "Недели красоты" => ["Уходы за лицом и телом", "Аппаратная косметология"],
        ];

        foreach ($promoServiceMap as $promoKeyword => $srvNames) {
            $promo = Promotion::where("name", "like", "%{$promoKeyword}%")->first();
            if ($promo) {
                $serviceIds = collect();
                foreach ($srvNames as $sName) {
                    $found = Service::where("name", "like", "%{$sName}%")->pluck("id");
                    $serviceIds = $serviceIds->merge($found);
                }
                if ($serviceIds->isNotEmpty()) {
                    $promo->services()->syncWithoutDetaching($serviceIds->unique()->all());
                }
            }
        }

        // Ensure all seeded entities across the 8 target tables have valid, unique slug, description, and keywords
        $targetModelClasses = [
            ServiceCategorySectionAll::class,
            ServiceCategorySection::class,
            ServiceCategory::class,
            Service::class,
            Specialist::class,
            Promotion::class,
            Project::class,
            Unco::class,
        ];

        foreach ($targetModelClasses as $modelClass) {
            $records = $modelClass::whereNull('slug')
                ->orWhere('slug', '')
                ->orWhereNull('description')
                ->orWhere('description', '')
                ->orWhereNull('keywords')
                ->orWhere('keywords', '')
                ->get();

            foreach ($records as $record) {
                if (empty($record->slug)) {
                    $record->slug = $record->generateUniqueSlug();
                }
                if (empty($record->description)) {
                    $record->description = $record->generateDefaultDescription();
                }
                if (empty($record->keywords)) {
                    $record->keywords = $record->generateDefaultKeywords();
                }
                $record->save();
            }
        }
    }
}

